//! Cargo-driven `ipconfig.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is ipconfig-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wmainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wmainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wmainCRTStartup"),
        o => panic!("ipconfig-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/conutils/libconutils.a", "engine:oldnames", "engine:pseh", "engine:chkstk", "sdk/lib/conutils/libconutils_rust.a"],
        "x86_64" => &["sdk/lib/conutils/libconutils.a", "engine:oldnames", "engine:pseh", "sdk/lib/conutils/libconutils_rust.a"],
        "aarch64" => &["sdk/lib/conutils/libconutils.a", "engine:oldnames", "engine:pseh", "engine:chkstk", "sdk/lib/conutils/libconutils_rust.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("ipconfig-rust")
        .resource_from_rc("base/applications/network/ipconfig/ipconfig.rc", "ipconfig_res")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/dnsapi/dnsapi.spec", "dnsapi.dll", "dnsapi")
        .import_lib("base/services/dhcpcsvc/dhcpcsvc.spec", "dhcpcsvc.dll", "dhcpcsvc")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
